<template><main class="mx-auto max-w-3xl px-4 py-10"><div class="mb-6"><span class="tag bg-blue-50 text-blue-700">Step 1 · 准备面试</span><h1 class="mt-3 text-3xl font-bold text-slate-900">配置你的模拟面试</h1><p class="mt-2 text-slate-500">岗位范围由 JD 和简历动态决定，公开网页资料仅作参考。</p></div><form class="card space-y-5 p-6" @submit.prevent="submit"><label class="block"><span class="mb-2 block text-sm font-medium">目标岗位 *</span><input v-model="jobTitle" required class="input" placeholder="例如：产品经理、前端工程师"></label><label class="block"><span class="mb-2 block text-sm font-medium">公司（可选）</span><input v-model="company" class="input" placeholder="公司名称"></label><label class="block"><span class="mb-2 block text-sm font-medium">岗位 JD *</span><textarea v-model="jd" required class="input h-40" placeholder="粘贴岗位职责和任职要求"></textarea></label><label class="block"><span class="mb-2 block text-sm font-medium">PDF 简历 *</span><input type="file" accept="application/pdf" required @change="file=$event.target.files?.[0]"/><p v-if="file" class="mt-2 text-sm text-emerald-600">已选择：{{file.name}}</p></label><label class="block"><span class="mb-2 block text-sm font-medium">公开资料 URL（可选，每行一个）</span><textarea v-model="urls" class="input h-24" placeholder="https://..."></textarea></label><p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{error}}</p><button :disabled="loading" class="btn-primary w-full">{{loading?'正在创建会话…':'创建并开始面试'}}</button></form></main></template>
<script setup lang="ts">import {createInterview} from '~/utils/api'; const jobTitle=ref(''),company=ref(''),jd=ref(''),urls=ref(''),file=ref<File>(),loading=ref(false),error=ref(''); async function submit(){if(!file.value)return; loading.value=true;error.value='';try{const f=new FormData();f.append('resume_pdf',file.value);f.append('job_title',jobTitle.value);f.append('company',company.value);f.append('job_description',jd.value);f.append('source_urls',JSON.stringify(urls.value.split('\n').map(x=>x.trim()).filter(Boolean)));const x=await createInterview(f);const failures=x.source_collection?.failures||[];if(failures.length)sessionStorage.setItem(`interview-source-notice-${x.session_id}`,`公开资料采集完成，但有 ${failures.length} 个网页未抓到正文；搜索摘要会保留在来源列表中。`);await navigateTo(`/interview/session/${x.session_id}`)}catch(e:any){error.value=e.message||'创建失败，请检查服务状态'}finally{loading.value=false}}</script>
